src/services/addressService.ts.fix:
Before deleting, read the row's is_default; after a successful delete, if it was default, promote the most recent remaining address:
async deleteAddress(addressId: string): Promise<void> {
  const { data: row } = await supabase.from('addresses').select('user_id,is_default').eq('id', addressId).single();
  const { error } = await supabase.from('addresses').delete().eq('id', addressId);
  if (error) throw error;
  if (row?.is_default) {
    const { data: rest } = await supabase.from('addresses').select('id').eq('user_id', row.user_id).order('created_at', { ascending: false }).limit(1);
    if (rest && rest.length) await supabase.from('addresses').update({ is_default: true }).eq('id', rest[0].id);
  }
}

