src/services/auth/securityService.ts.fix:
Inspect the returned error and only clear on a genuinely missing session:

export async function reloadUser(): Promise<void> {
  try {
    const { data, error } = await supabase.auth.getUser();
    if (error) {
      // Genuine sign-out clears; transient network keeps last-known user.
      if ((error as any)?.name === 'AuthSessionMissingError' || (error as any)?.status === 401 || (error as any)?.status === 403) {
        cachedUser = null;
      }
      return;
    }
    cachedUser = data?.user ?? null;
  } catch { /* keep last-known cache on transient failure */ }
}

